WITH cleaned AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, CAST(temp_c AS INT) AS temp_c_int FROM device_readings WHERE reading_ts > TO_DATE('2025-09-01') AND pressure < 1006), enriched AS (SELECT *, LEAD(pressure) OVER (PARTITION BY device_code ORDER BY temp_c_int, id) AS next_pressure, LAG(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c_int, id) AS prev_status_bits, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c_int, id) AS seq_no FROM cleaned), cleaned_device_readings AS (SELECT *, CONCAT_WS('-', firmware, device_code) AS firmware_device_code_key, ROUND(seq_no * 0.85, 2) AS seq_no_scaled FROM enriched WHERE reading_ts > TIMESTAMP '2025-09-01 06:00:00'), valid AS (SELECT *, seq_no_scaled - status_bits AS seq_no_scaled_minus_status_bits, ROUND(status_bits * 100, 2) AS status_bits_scaled FROM cleaned_device_readings WHERE prev_status_bits <> 12), with_windows AS (SELECT id, device_code, humidity, status_bits, firmware, prev_status_bits, firmware_device_code_key, seq_no_scaled_minus_status_bits, status_bits_scaled, SUM(pressure) OVER (ORDER BY seq_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_pressure, AVG(seq_no) OVER (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS seq_no_avg_2_prior, CUME_DIST() OVER (PARTITION BY device_code ORDER BY seq_no_scaled_minus_status_bits NULLS LAST) AS seq_no_scaled_minus_status_bits_cume_dist, AVG(pressure) OVER (ORDER BY humidity, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS pressure_avg_3 FROM valid), totals AS (SELECT CASE WHEN seq_no_avg_2_prior >= 8 THEN 'HIGH' ELSE 'LOW' END AS seq_no_avg_2_prior_tier, device_code, ROUND(SUM(status_bits) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS status_bits_per_dv_04, SUM(seq_no_scaled_minus_status_bits_cume_dist) AS total_seq_no_scaled_minus_status_bits_cume_dist, STDDEV_SAMP(humidity) AS humidity_stddev, COUNT(DISTINCT id) AS distinct_ids FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN seq_no_avg_2_prior >= 8 THEN 'HIGH' ELSE 'LOW' END, device_code), (CASE WHEN seq_no_avg_2_prior >= 8 THEN 'HIGH' ELSE 'LOW' END), ()) HAVING total_seq_no_scaled_minus_status_bits_cume_dist > 0) SELECT seq_no_avg_2_prior_tier, device_code, status_bits_per_dv_04, humidity_stddev, distinct_ids FROM totals ORDER BY device_code DESC NULLS LAST
